const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const a = data.slice(1, 1 + n);

const indices = Array.from({ length: n }, (_, i) => i);
indices.sort((i, j) => a[j] - a[i]);

const active = new Uint8Array(n + 2);
let seg = 0;
let maxSeg = 0;
let i = 0;

