  const h = a[indices[i]];
  let j = i;
  while (j < n && a[indices[j]] === h) j++;

  for (let k = i; k < j; k++) {
    const pos = indices[k] + 1;
    active[pos] = 1;
    const left = active[pos - 1];
    const right = active[pos + 1];
    if (left && right) {
      seg--;
    } else if (!left && !right) {
      seg++;
    }
  }

  if (seg > maxSeg) maxSeg = seg;
